    old,tor,tr,nop,nr,mia,mr,nyk,yr,uta,ur,bos,br,phi,pr,bkn,bkr,dal,dr,gsw,gr,lac,lr,lal,lar,por,porr,den,denr,ind,ir,orl,orlr,hou,hour,cha,char,miag,miagr,cle,cler,atl,atlr,was,wasr,detlater,detlaterr=(src[p] for p in FILES)
