    additions=[(r,FILES[1],FILES[2]) for r in tor['rows']]+[(nop['selected_result'],FILES[3],FILES[4])]+[(r,FILES[7],FILES[8]) for r in nyk['selected_games']]+[(uta['selected_game'],FILES[9],FILES[10])]+[(r,FILES[11],FILES[12]) for r in bos['selected_games']]+[(r,FILES[13],FILES[14]) for r in phi['selected_games']]+[(r,FILES[15],FILES[16]) for r in bkn['selected_games']]+[(r,FILES[17],FILES[18]) for r in dal['selected_games']]+[(r,FILES[19],FILES[20]) for r in gsw['selected_games']]+[(r,FILES[21],FILES[22]) for r in lac['selected_games']]+[(r,FILES[23],FILES[24]) for r in lal['selected_games']]+[(r,FILES[25],FILES[26]) for r in por['selected_games']]+[(r,FILES[27],FILES[28]) for r in den['selected_games']]+[(r,FILES[29],FILES[30]) for r in ind['selected_games']]+[(r,FILES[31],FILES[32]) for r in orl['selected_games']]+[(r,FILES[33],FILES[34]) for r in hou['selected_games']]+[(r,FILES[35],FILES[36]) for r in cha['selected_games']]+[(r,FILES[37],FILES[38]) for r in miag['selected_games']]+[(r,FILES[39],FILES[40]) for r in cle['selected_games']]+[(r,FILES[41],FILES[42]) for r in atl['selected_games']]+[(r,FILES[43],FILES[44]) for r in was['selected_games']]+[(r,FILES[45],FILES[46]) for r in detlater['selected_games']]
